def min_operations_to_ones(n, a):
    if 1 in a:
        return n - a.count(1)

    # Check if there's any gcd of the whole array that is 1
    overall_gcd = a[0]
    for i in range(1, n):
        overall_gcd = math.gcd(overall_gcd, a[i])

    if overall_gcd > 1:
        return -1

    # If there's no gcd of the whole array that is 1, count operations needed
    # to make all pairs gcd to 1
    min_operations = float('inf')
    for i in range(n):
        current_gcd = a[i]
        current_operations = n - 1
        for j in range(n):
            if j != i:
                current_gcd = math.gcd(current_gcd, a[j])
                current_operations -= 1
                if current_gcd == 1:
                    min_operations = min(min_operations, n - 1 + current_operations)
                    break

    return min_operations

